changeSet.sql:
ALTER TABLE ${ARENA_DB_SCHEMA}.customer ADD COLUMN owner_managed BOOLEAN NOT NULL DEFAULT false, ADD COLUMN setup_review_confirmed BOOLEAN NOT NULL DEFAULT false, ADD COLUMN setup_status VARCHAR(20) NOT NULL DEFAULT 'INCOMPLETE', ADD COLUMN setup_evaluated_at TIMESTAMP;
ALTER TABLE ${ARENA_DB_SCHEMA}.app_user ADD COLUMN keycloak_subject VARCHAR(100);
CREATE UNIQUE INDEX app_user_username_ci_unique ON ${ARENA_DB_SCHEMA}.app_user(lower(username));
CREATE UNIQUE INDEX app_user_email_ci_unique ON ${ARENA_DB_SCHEMA}.app_user(lower(trim(email))) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX app_user_subject_unique ON ${ARENA_DB_SCHEMA}.app_user(keycloak_subject) WHERE keycloak_subject IS NOT NULL;
CREATE UNIQUE INDEX academy_one_active_owner ON ${ARENA_DB_SCHEMA}.app_user(customer_id) WHERE role='OWNER' AND is_active=true AND customer_id IS NOT NULL;
ALTER TABLE ${ARENA_DB_SCHEMA}.academy_staff ADD COLUMN designation VARCHAR(30) NOT NULL DEFAULT 'GENERAL_STAFF', ADD COLUMN keycloak_subject VARCHAR(100), ADD COLUMN login_state VARCHAR(24) NOT NULL DEFAULT 'NOT_ENABLED', ADD COLUMN notification_state VARCHAR(24) NOT NULL DEFAULT 'NOT_SENT', ADD COLUMN invitation_expires_at TIMESTAMP, ADD COLUMN invitation_sent_at TIMESTAMP, ADD COLUMN login_username VARCHAR(100), ADD COLUMN access_valid_after TIMESTAMP;
UPDATE ${ARENA_DB_SCHEMA}.academy_staff SET designation='COACH' WHERE role='COACH';
UPDATE ${ARENA_DB_SCHEMA}.academy_staff SET login_state='LEGACY_LINKED' WHERE app_user_id IS NOT NULL;
CREATE UNIQUE INDEX staff_subject_unique ON ${ARENA_DB_SCHEMA}.academy_staff(keycloak_subject) WHERE keycloak_subject IS NOT NULL;
CREATE UNIQUE INDEX staff_username_unique ON ${ARENA_DB_SCHEMA}.academy_staff(lower(login_username)) WHERE login_username IS NOT NULL;
CREATE TABLE ${ARENA_DB_SCHEMA}.membership_role (staff_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.academy_staff(id), role VARCHAR(20) NOT NULL CHECK(role IN ('MANAGER','INSTRUCTOR','STAFF')), PRIMARY KEY(staff_id,role));
CREATE TABLE ${ARENA_DB_SCHEMA}.academy_play_area (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, created_by VARCHAR(100), updated_by VARCHAR(100), academy_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.customer(id), sport_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, code VARCHAR(64) NOT NULL, kind VARCHAR(20) NOT NULL CHECK(kind IN ('COURT','TABLE','FIELD','OTHER')), capacity INTEGER CHECK(capacity>0), active BOOLEAN NOT NULL, UNIQUE(academy_id,code), FOREIGN KEY(sport_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_sport(id,academy_id));
CREATE INDEX academy_play_area_scope ON ${ARENA_DB_SCHEMA}.academy_play_area(academy_id,sport_id,active);
